window.__finlexDocLoaded(194,{"id":194,"articles":[{"id":4879,"no":"第一条","heading":"","text":"为了规范注册会计师在财务报表审计中与比较信息相关的责任，制定本准则。","seq":0,"links":[{"doc_id":184,"tier":"L3","score":64,"rel_kind":"cites","target_seq":1,"target_art_no":"第二条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1511号——比较信息：对应数据和比较财务报表（2019年2月20日修订）》"},{"doc_id":184,"tier":"L3","score":64,"rel_kind":"cites","target_seq":14,"target_art_no":"第十五条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1511号——比较信息：对应数据和比较财务报表（2019年2月20日修订）》"},{"doc_id":199,"tier":"L3","score":64,"rel_kind":"cites","target_seq":33,"target_art_no":"第三十四条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1511号——比较信息：对应数据和比较财务报表（2019年2月20日修订）》"}]},{"id":4880,"no":"第二条","heading":"","text":"当上期财务报表已由前任注册会计师审计或未经审计时，《中国注册会计师审计准则第1331号——首次审计业务涉及的期初余额》对期初余额的相关规定同样适用。","seq":1,"links":[{"doc_id":184,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1331号——首次审计业务涉及的期初余额（2022年12月22日修订）》"}]},{"id":4881,"no":"第三条","heading":"","text":"财务报表中列报的比较信息的性质取决于适用的财务报告编制基础的要求。比较信息包括对应数据和比较财务报表，相应地，注册会计师履行比较信息的报告责任有两种不同的方法。采用的方法通常由法律法规规定，但也可能在业务约定条款中作出约定。","seq":2},{"id":4882,"no":"第四条","heading":"","text":"本准则第三条提及的两种方法导致审计报告存在下列主要差异： **（一）对于对应数据，审计意见仅提及本期；** （二）对于比较财务报表，审计意见提及列报的财务报表所属的各期。本准则对每种方法分别提出不同的审计报告要求。 ## 第二章 定义","seq":3},{"id":4883,"no":"第五条","heading":"","text":"比较信息，是指包含于财务报表中的、符合适用的财务报告编制基础的、与一个或多个以前期间相关的金额和披露。","seq":4},{"id":4884,"no":"第六条","heading":"","text":"对应数据，属于比较信息，是指作为本期财务报表组成部分的上期金额和相关披露，这些金额和披露只能和与本期相关的金额和披露（称为“本期数据”）联系起来阅读。对应数据列报的详细程度主要取决于其与本期数据的相关程度。","seq":5},{"id":4885,"no":"第七条","heading":"","text":"比较财务报表，属于比较信息，是指为了与本期财务报表相比较而包含的上期金额和相关披露。比较财务报表包含信息的详细程度与本期财务报表包含信息的详细程度相似。如果上期金额和相关披露已经审计，则将在审计意见中提及。","seq":6},{"id":4886,"no":"第八条","heading":"","text":"当比较信息包括一期以上的金额和相关披露时，本准则所称“上期”应理解为“以前数期”。 ## 第三章 目标","seq":7},{"id":4887,"no":"第九条","heading":"","text":"注册会计师的目标是： （一）获取充分、适当的审计证据，确定在财务报表中包含的比较信息是否在所有重大方面按照适用的财务报告编制基础有关比较信息的要求进行列报； **（二）按照注册会计师的报告责任出具审计报告。** ## 第四章 要求 ### 第一节 审计程序","seq":8},{"id":4888,"no":"第十条","heading":"","text":"注册会计师应当确定财务报表中是否包括适用的财务报告编制基础要求的比较信息，以及比较信息是否得到恰当分类。基于上述目的，注册会计师应当评价： （一）比较信息是否与上期财务报表列报的金额和相关披露一致，如果必要，比较信息是否已经重述； （二）在比较信息中反映的会计政策是否与本期采用的会计政策一致，如果会计政策已发生变更，这些变更是否得到恰当处理并得到充分列报。","seq":9},{"id":4889,"no":"第十一条","heading":"","text":"在实施本期审计时，如果注意到比较信息可能存在重大错报，注册会计师应当根据实际情况追加必要的审计程序，获取充分、适当的审计证据，以确定是否存在重大错报。如果上期财务报表已经审计，注册会计师还应当遵守《中国注册会计师审计准则第1332号——期后事项》的相关规定。如果上期财务报表已经得到更正，注册会计师应当确定比较信息与更正后的财务报表是否一致。","seq":10,"links":[{"doc_id":185,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1332号——期后事项（2016年12月23日修订）》"}]},{"id":4890,"no":"第十二条","heading":"","text":"注册会计师应当按照《中国注册会计师审计准则第1341号——书面声明》的规定，获取与审计意见中提及的所有期间相关的书面声明。对于管理层作出的、更正上期财务报表中影响比较信息的重大错报的任何重述，注册会计师还应当获取特定书面声明。 ### 第二节 审计报告：对应数据","seq":11,"links":[{"doc_id":186,"tier":"L3","score":72,"rel_kind":"cites","target_seq":18,"target_art_no":"第十九条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1511号——比较信息：对应数据和比较财务报表（2019年2月20日修订）》第12条"},{"doc_id":186,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1341号——书面声明（2022年12月22日修订）》"}]},{"id":4891,"no":"第十三条","heading":"","text":"当财务报表中列报对应数据时，除本准则第十四条、第十五条和第十七条描述的情形外，审计意见不应提及对应数据。","seq":12},{"id":4892,"no":"第十四条","heading":"","text":"如果以前针对上期财务报表发表了保留意见、无法表示意见或否定意见，且导致非无保留意见的事项仍未解决，注册会计师应当对本期财务报表发表非无保留意见。在审计报告的导致非无保留意见的事项段中，注册会计师应当分下列两种情况予以处理： （一）如果未解决事项对本期数据的影响或可能的影响是重大的，注册会计师应当在导致非无保留意见事项段中同时提及本期数据和对应数据； （二）如果未解决事项对本期数据的影响或可能的影响不重大，注册会计师应当说明，由于未解决事项对本期数据和对应数据之间可比性的影响或可能的影响，因此发表了非无保留意见。","seq":13},{"id":4893,"no":"第十五条","heading":"","text":"如果注册会计师已经获取上期财务报表存在重大错报的审计证据，而以前对该财务报表发表了无保留意见，且对应数据未经适当重述或恰当披露，注册会计师应当就包括在财务报表中的对应数据，在审计报告中对本期财务报表发表保留意见或否定意见。","seq":14},{"id":4894,"no":"第十六条","heading":"","text":"如果上期财务报表已由前任注册会计师审计，注册会计师在审计报告中可以提及前任注册会计师对对应数据出具的审计报告。当注册会计师决定提及时，应当在审计报告的其他事项段中说明： **（一）上期财务报表已由前任注册会计师审计；** （二）前任注册会计师发表的意见的类型（如果是非无保留意见，还应当说明发表非无保留意见的理由）； **（三）前任注册会计师出具的审计报告的日期。**","seq":15,"links":[{"doc_id":192,"tier":"L3","score":72,"rel_kind":"cites","target_seq":12,"target_art_no":"第十三条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1511号——比较信息：对应数据和比较财务报表（2019年2月20日修订）》第16条"}]},{"id":4895,"no":"第十七条","heading":"","text":"如果上期财务报表未经审计，注册会计师应当在审计报告的其他事项段中说明对应数据未经审计。但这种说明并不减轻注册会计师获取充分、适当的审计证据，以确定期初余额不含有对本期财务报表产生重大影响的错报的责任。 ### 第三节 审计报告：比较财务报表","seq":16},{"id":4896,"no":"第十八条","heading":"","text":"当列报比较财务报表时，审计意见应当提及列报财务报表所属的各期，以及发表的审计意见涵盖的各期。","seq":17},{"id":4897,"no":"第十九条","heading":"","text":"当因本期审计而对上期财务报表发表审计意见时，如果对上期财务报表发表的意见与以前发表的意见不同，注册会计师应当按照《中国注册会计师审计准则第1503号——在审计报告中增加强调事项段和其他事项段》的规定，在其他事项段中披露导致不同意见的实质性原因。","seq":18,"links":[{"doc_id":192,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师审计准则第1503号——在审计报告中增加强调事项段和其他事项段（2022年1月5日修订）》"}]},{"id":4898,"no":"第二十条","heading":"","text":"如果上期财务报表已由前任注册会计师审计，除非前任注册会计师对上期财务报表出具的审计报告与财务报表一同对外提供，注册会计师除对本期财务报表发表意见外，还应当在其他事项段中说明： **（一）上期财务报表已由前任注册会计师审计；** （二）前任注册会计师发表的意见的类型（如果是非无保留意见，还应当说明发表非无保留意见的理由）； **（三）前任注册会计师出具的审计报告的日期。**","seq":19},{"id":4899,"no":"第二十一条","heading":"","text":"如果认为存在影响上期财务报表的重大错报，而前任注册会计师以前出具了无保留意见的审计报告，注册会计师应当就此与适当层级的管理层沟通，并要求其告知前任注册会计师。注册会计师还应当与治理层进行沟通，除非治理层全部成员参与管理被审计单位。如果上期财务报表已经更正，且前任注册会计师同意对更正后的上期财务报表出具新的审计报告，注册会计师应当仅对本期财务报表出具审计报告。","seq":20,"links":[{"doc_id":167,"tier":"L3","score":72,"rel_kind":"cites","target_seq":23,"target_art_no":"第二十四条","dir":"in","note":"正文显式引用《中国注册会计师审计准则第1511号——比较信息：对应数据和比较财务报表（2019年2月20日修订）》第21条"}]},{"id":4900,"no":"第二十二条","heading":"","text":"如果上期财务报表未经审计，注册会计师应当在其他事项段中说明比较财务报表未经审计。但这种说明并不减轻注册会计师获取充分、适当的审计证据，以确定期初余额不含有对本期财务报表产生重大影响的错报的责任。 ## 第五章 附则","seq":21},{"id":4901,"no":"第二十三条","heading":"","text":"本准则自2019年7月1日起施行。","seq":22}]});
